import { escapeAttribute as escapeAttr, escapeHtml, safeProfile } from "./client-safety.js";
import { DATE_ACTIVITIES, DATE_MINUTES, dateQuote, settleDate } from "./virtual-date.js";

const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const storeKey = "luma-state-v1";
const CHECKPOINT_VERSION = "v190";
const CHECKPOINT_BASE_VERSION = "v189";
const profiles = [
  {id:"nora",name:"Nora",gender:"woman",age:31,city:"Williamsburg",distance:2,job:"Creative director",intent:"Something real",online:true,image:"assets/profile-nora.jpg",bio:"Art direction by day, tiny jazz rooms by night. Looking for someone kind, curious, and ready to build something real.",tags:["Live music","Sushi hunts","Museums"],match:true},
  {id:"julian",name:"Julian",gender:"man",age:33,city:"Fort Greene",distance:4,job:"Architect",intent:"Long-term partner",online:false,image:"assets/profile-julian.jpg",bio:"I design public spaces, make an unreasonable amount of pasta, and never skip Sunday morning walks.",tags:["Architecture","Cooking","Vinyl"],match:false},
  {id:"maya",name:"Maya",gender:"woman",age:29,city:"Park Slope",distance:5,job:"Pediatric nurse",intent:"A real relationship",online:true,emoji:"🌺",bio:"Soft heart, sharp humor. Big on family, bookstores, and spontaneous weekend drives.",tags:["Books","Road trips","Brunch"],match:true},
  {id:"theo",name:"Theo",gender:"man",age:35,city:"DUMBO",distance:7,job:"Music producer",intent:"Dating with intention",online:true,emoji:"🎧",bio:"Studio nights, beach mornings, and the perfect old-school playlist. Tell me what song changed your life.",tags:["R&B","Travel","Photography"],match:false},
  {id:"sam",name:"Sam",gender:"nonbinary",age:30,city:"Crown Heights",distance:3,job:"Chef",intent:"Something meaningful",online:false,emoji:"🍜",bio:"Restaurant chef with a quiet side. Happiest cooking for people I care about.",tags:["Food","Dogs","Comedy"],match:true}
];
const defaults={onboarded:false,tab:"discover",index:0,liked:[],passed:[],matches:[],messages:{},blocked:[],premium:false,theme:"dark",filters:{distance:25,minAge:18,maxAge:99,type:"all",online:false},notifications:true,verification:"verified",wallet:{spending:1000,earned:0,autoCashout:false,payout:null},callRates:{voice:25,video:50},vaults:[],transactions:[{type:"Signup credit",amount:1000,date:"Today",withdrawable:false}],profile:{name:"Alex",age:30,gender:"prefer_not_to_say",lookingFor:"all",city:"Brooklyn",job:"Entrepreneur",bio:"Good energy, honest conversations, and building a life worth sharing.",intent:"Long-term relationship",emoji:"✨",badges:["Verified human","New glow"]}};
let state=load(); let modal=null; let activeChat=null; let confirmedSessionToken=null;
const launchParams=new URLSearchParams(location.search);
const partnerDemo=launchParams.get("partner")==="1";
if(launchParams.get("preview")==="1"||partnerDemo)state={...state,onboarded:true};
if(partnerDemo){
  state={...state,onboarded:true,tab:"discover",matches:[...new Set([...(state.matches||[]),"nora","maya"])],messages:{...(state.messages||{}),nora:(state.messages?.nora?.length?state.messages.nora:[{me:false,text:"Hey! I liked your profile. Want to try a Luma Virtual Date?",time:"Now"}])}};
}
function load(){try{return {...defaults,...JSON.parse(localStorage.getItem(storeKey)||"{}")}}catch{return structuredClone(defaults)}}
function save(){localStorage.setItem(storeKey,JSON.stringify(state))}
async function verifySavedSession(){
  const token=localStorage.getItem("luma-auth-token");if(!token)return;
  try{
    const response=await fetch("/api/auth/session",{headers:{authorization:`Bearer ${token}`},cache:"no-store"});
    if(localStorage.getItem("luma-auth-token")!==token)return;
    if(response.status===401||response.status===403){localStorage.removeItem("luma-auth-token");confirmedSessionToken=null;modal=null;render();toast("Account session expired or unavailable. Please sign in again.");return}
    if(!response.ok)return;
    const result=await response.json();
    if(localStorage.getItem("luma-auth-token")!==token||result.authenticated!==true||!["active","pending_verification"].includes(result.accountStatus))return;
    confirmedSessionToken=token;if(state.onboarded&&state.tab==="me")render();
  }catch{/* A network failure cannot confirm or revoke the stored sign-in. */}
}
function toast(text){const el=$("#toast");el.textContent=text;el.classList.add("show");clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove("show"),2200)}
function icon(name){return {pin:"⌖",filter:"☷",x:"×",star:"★",heart:"♥",chat:"●",discover:"⌁",matches:"♡",inbox:"◌",me:"♙",back:"‹",more:"•••"}[name]||name}
function photo(source,cls=""){const p=safeProfile(source);return p.image?`<img class="${escapeAttr(cls)}" src="${p.image}" alt="${p.name}">`:`<div class="avatar-fallback ${escapeAttr(cls)}" aria-label="${p.name}">${p.emoji||"✨"}</div>`}
function currentProfiles(){return profiles.filter(p=>!state.passed.includes(p.id)&&!state.liked.includes(p.id)&&!state.blocked.includes(p.id)&&p.distance<=state.filters.distance&&p.age>=state.filters.minAge&&p.age<=state.filters.maxAge&&(state.filters.type==="all"||p.gender===state.filters.type)&&(!state.filters.online||p.online))}
function nav(){return `<nav class="nav">${[["discover","discover","Discover"],["matches","matches","Matches"],["inbox","inbox","Inbox"],["me","me","Me"]].map(([tab,ic,label])=>`<button data-tab="${tab}" class="${state.tab===tab?"active":""}"><span class="ico">${icon(ic)}</span>${label}</button>`).join("")}</nav>`}
function header(extra=""){return `<header class="topbar"><div><div class="brand">luma<i>.</i></div><div class="tag">Find your frequency</div></div>${extra}</header>`}
function shell(content,extra=""){return `<main class="app-shell">${header(extra)}${partnerDemo?`<div class="partner-demo-banner"><b>PARTNER DEMO</b><span class="demo-checkpoint">${CHECKPOINT_VERSION} · VERIFIED CHECKPOINT</span><span>Interactive preview · no real payments, payouts, identity verification, live calls/video, push delivery, or production signing</span><div class="demo-provider-status" aria-label="Demo provider status"><em>PRODUCT LOGIC VERIFIED</em><em class="gated">EXTERNAL PROVIDERS GATED</em></div><div class="partner-demo-actions"><button class="demo-tour-btn" id="demo-runbook">Start 7-min demo</button><button class="demo-tour-btn" id="demo-tour">Investor tour</button><button class="demo-reset-btn" id="demo-reset">Reset demo</button></div></div>`:""}<section class="content">${content}</section>${nav()}</main>${modal||""}`}
function resetPartnerDemo(){
  if(!partnerDemo)return;
  clearInterval(window.lumaVirtualDateClock);window.lumaVirtualDateClock=null;
  const theme=state.theme;
  state=structuredClone(defaults);
  state={...state,onboarded:true,theme,tab:"discover",matches:["nora","maya"],messages:{nora:[{me:false,text:"Hey! I liked your profile. Want to try a Luma Virtual Date?",time:"Now"}]}};
  modal=null;activeChat=null;save();render();toast("Partner Demo reset for a clean investor walkthrough");
}
function render(){syncDate();document.documentElement.classList.toggle("light",state.theme==="light"); if(!state.onboarded)return renderOnboarding(); let body=state.tab==="discover"?discover():state.tab==="matches"?matches():state.tab==="inbox"?inbox():me(); $("#app").innerHTML=activeChat?chatView():shell(body,topActions());bind();bindAccountSecurity()}
function topActions(){if(state.tab==="discover")return `<div class="row"><button class="pill" id="location">${icon("pin")} ${escapeHtml(state.profile.city)}</button><button class="icon-btn primary" id="filters" aria-label="Filters">${icon("filter")}</button></div>`;return ""}
function resonance(p){return 72+((p.tags.join("").length+p.age+p.distance*3)%25)}
function discover(){const ps=currentProfiles();if(!ps.length)return `<div class="hero"><h1>Your daily <span>frequency</span> is complete.</h1><p>Adjust your preferences or return when new signals arrive.</p></div><div class="empty"><div class="big">✦</div><button class="primary" id="reset-deck">Refresh connections</button></div>`;return `<div class="hero"><div class="eyebrow">TODAY’S FREQUENCY</div><h1>People who <span>fit your energy.</span></h1><p>No endless swiping. Luma explains why each person may connect with you.</p></div><div class="frequency-summary"><div class="frequency-orbit"><span>${ps.length}</span><small>signals</small></div><div><b>Your connection mix</b><p>${state.filters.minAge}–${state.filters.maxAge} · ${state.filters.type==="all"?"Everyone":state.filters.type}</p></div><button class="secondary" id="filters">Tune</button></div>${topThirty(ps)}<div class="signal-list">${ps.map(signalCard).join("")}</div><p class="hint">Fresh curated connections appear as your frequency learns.</p>`}
function topThirty(ps){return `<section class="top30"><div class="section-title"><div><div class="eyebrow">SPONSORED · PAY PER PROFILE VIEW</div><h2>Luma Top 30</h2></div><button class="secondary" id="promote-me">Promote me</button></div><div class="top30-row">${ps.slice(0,3).map((source,i)=>{const p=safeProfile(source);return `<button class="top30-person" data-profile="${p.id}"><span class="rank">#${i+1}</span>${p.image?`<img src="${p.image}" alt="${p.name}">`:`<span class="top30-face">${p.emoji}</span>`}<b>${p.name}</b><small>Sponsored</small></button>`}).join("")}</div></section>`}
function signalCard(source){const score=resonance(source);const p=safeProfile(source);return `<article class="signal-card" data-profile="${p.id}"><div class="signal-photo">${p.image?`<img src="${p.image}" alt="${p.name}">`:`<div class="signal-fallback">${p.emoji}</div>`}<span class="resonance">${score}% resonance</span>${p.online?'<span class="live-dot">● live</span>':""}</div><div class="signal-body"><div class="signal-name"><div><h2>${p.name}, ${p.age}</h2><p>${p.city} · ${p.distance} mi</p></div><span class="verified-mark" title="Verified">✓</span></div><p class="signal-prompt">“${p.bio.split(".")[0]}.”</p><div class="why"><small>WHY YOU ALIGN</small><div class="chips">${p.tags.slice(0,2).map(x=>`<span class="chip">${x}</span>`).join("")}<span class="chip">${p.intent}</span></div></div><div class="signal-actions"><button class="secondary" data-act="pass" data-id="${p.id}">Not my frequency</button><button class="primary" data-act="like" data-id="${p.id}">Connect ✦</button></div></div></article>`}
function card(source,behind){const p=safeProfile(source);return `<article class="profile-card ${behind?"behind":""}" data-profile="${p.id}">${p.image?`<img src="${p.image}" alt="${p.name}">`:`<div class="fallback">${p.emoji}</div>`}<div class="overlay"></div><div class="card-top"><span class="badge">${icon("pin")} ${p.distance} mi away</span>${p.online?'<span class="badge online">● Online now</span>':""}</div><div class="card-info"><h2>${p.name}, ${p.age}</h2><p>${p.city} · ${p.job}</p><p class="intent">Here for <b>${p.intent}</b></p><div class="chips">${p.tags.slice(0,3).map(x=>`<span class="chip">${x}</span>`).join("")}</div></div></article>`}
function matches(){const ms=profiles.filter(p=>state.matches.includes(p.id)&&!state.blocked.includes(p.id));return `<div class="section-title"><h2>Your matches</h2><span class="muted">${ms.length}</span></div>${state.virtualDate?`<button class="setting-row" data-resume-date><span>Return to active virtual date</span><span>›</span></button>`:""}${ms.length?`<div class="grid">${ms.map(source=>{const p=safeProfile(source);return `<article class="match-card" data-open-chat="${p.id}">${photo(source)}<div class="meta"><h3>${p.name}, ${p.age}</h3><small class="muted">${p.online?'<i class="dot"></i> Online now':p.city}</small></div></article>`}).join("")}</div>`:`<div class="empty"><div class="big">♡</div><h3>No matches yet</h3><p>When the feeling is mutual, they’ll appear here.</p><button class="primary" data-tab="discover">Start discovering</button></div>`}`}
function inbox(){const ms=profiles.filter(p=>state.matches.includes(p.id)&&!state.blocked.includes(p.id));return `<div class="section-title"><h2>Messages</h2><button class="secondary" id="safety">Safety</button></div>${ms.length?`<div class="list">${ms.map(source=>{const msgs=state.messages[source.id]||[];const last=msgs.at(-1);const p=safeProfile(source);return `<article class="chat-row" data-open-chat="${p.id}">${p.image?`<img class="avatar" src="${p.image}" alt="${p.name}">`:`<div class="avatar">${p.emoji}</div>`}<div class="grow"><b>${p.name}</b><div class="muted truncate">${last?escapeHtml(last.text):"You matched! Say hello."}</div></div><span class="time">${last?escapeHtml(last.time):"Now"}</span></article>`}).join("")}</div>`:`<div class="empty"><div class="big">◌</div><h3>Your inbox is quiet</h3><p>Match with someone to start a conversation.</p></div>`}`}
function me(){const p=state.profile;const w=state.wallet||defaults.wallet;return `<div class="policy-card"><b>${localStorage.getItem("luma-auth-token")?(confirmedSessionToken===localStorage.getItem("luma-auth-token")?"Server session connected · invitation tools":"Saved sign-in · server session unconfirmed"):"Local preview profile"}</b>${localStorage.getItem("luma-auth-token")?'<button class="secondary" id="check-account-session" style="margin-top:10px">Check account session</button>':""}<p>The name, badge, and wallet below are demo examples, not your verified identity or live balance.</p></div><div class="profile-head"><div class="me-avatar">${escapeHtml(p.emoji)}</div><div class="verified-title"><h2>${escapeHtml(p.name)}, ${Number(p.age)}</h2><span class="verified-mark" aria-label="Preview profile">◇</span></div><p class="muted">${escapeHtml(p.city)} · ${escapeHtml(p.job)}</p><div class="badge-row">${(p.badges||["Verified human"]).map(b=>`<span class="achievement">✦ ${escapeHtml(b)}</span>`).join("")}</div><button class="primary" id="edit-profile">Edit profile</button></div><button class="money-card" id="wallet"><div><div class="eyebrow">LUMA BALANCE</div><strong>$${((w.spending+w.earned)/100).toFixed(2)}</strong><small>$${(w.earned/100).toFixed(2)} eligible earnings</small></div><span>Wallet ›</span></button><div class="stats"><div class="stat"><b>${state.liked.length}</b><small class="muted">Connections</small></div><div class="stat"><b>${state.matches.length}</b><small class="muted">Matches</small></div><div class="stat"><b>${Object.values(state.messages).flat().length}</b><small class="muted">Messages</small></div></div><div class="settings"><button class="setting-row" id="creator-studio"><span>✦ Creator studio</span><span>Rates & promotion ›</span></button><button class="setting-row" id="vault-center"><span>🔐 My private vaults</span><span>›</span></button><button class="setting-row" id="bundles"><span>💜 Credit bundles</span><span>›</span></button><button class="setting-row" id="premium"><span>✦ Luma Premium</span><b class="accent">${state.premium?"Active":"Upgrade"}</b></button>${localStorage.getItem("luma-auth-token")?"":'<button class="setting-row" id="account-login"><span>Sign in for invitation tools</span><span>›</span></button>'}<button class="setting-row" id="virtual-date-notices"><span>💜 Virtual Date notices</span><span>›</span></button><button class="setting-row" id="active-date-safety"><span>🛡 Active date safety</span><span>Leave control ›</span></button><button class="setting-row" id="virtual-date-check-ins"><span>✦ Private date check-ins</span><span>›</span></button><button class="setting-row" id="notify"><span>Notifications</span><i class="switch ${state.notifications?"on":""}"></i></button><button class="setting-row" id="theme"><span>Appearance</span><span>${state.theme==="dark"?"Dark":"Light"}</span></button><button class="setting-row" id="safety"><span>🛡 Safety center</span><span>›</span></button><button class="setting-row" id="privacy"><span>Privacy & account</span><span>›</span></button><button class="setting-row" id="logout"><span>Log out</span><span>›</span></button>${state.virtualDate?`<button class="setting-row" data-resume-date><span>Resume virtual date</span><span>›</span></button>`:""}${(state.dateHistory||[]).filter(d=>d.usedMinutes>0&&!d.feedback).slice(-1).map(d=>`<button class="setting-row" data-date-feedback="${escapeAttr(d.id)}"><span>Rate your virtual date</span><span>›</span></button>`).join("")}</div>`}
function modalWrap(inner){return `<div class="modal-wrap" id="modal-wrap"><div class="modal">${inner}</div></div>`}
function investorBusinessModel(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">INVESTOR SNAPSHOT</div><h2>Designed for multiple revenue paths</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">Luma combines connection, paid communication, creator tools, and discovery promotion while keeping the core signup experience accessible.</p><div class="investor-model-grid"><div><b>💜 Paid interactions</b><small>Gifts plus user-priced voice/video concepts, subject to provider, policy, verification, and billing integration.</small></div><div><b>✦ Discovery promotion</b><small>Top 30 visibility with user-controlled promotion spend capped by available balance.</small></div><div><b>🔐 Private vaults</b><small>Permission-based photo/video access concepts with separate pricing controls.</small></div><div><b>◈ Platform share</b><small>Creator earnings and platform revenue are ledger-driven concepts; production percentages and settlement require final commercial configuration.</small></div></div><div class="policy-card"><b>Investor-ready distinction</b><p>The demo shows product flows and monetization surfaces. It does not represent processor approval, booked revenue, verified users, completed payouts, or live call infrastructure.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorWhyLuma(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">WHY LUMA</div><h2>Connection with more ways to engage</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">The investor story is not one feature. Luma brings discovery, intentional dating, private communication, creator controls and monetization concepts into one safety-aware experience.</p><div class="why-luma-grid"><div><span>01</span><b>Curated discovery</b><small>Frequency-style recommendations explain why people may align instead of presenting an unexplained swipe queue.</small></div><div><span>02</span><b>Virtual Dating</b><small>15/30/60-minute structured dates can use activities, invitations, extensions and private post-date check-ins.</small></div><div><span>03</span><b>User-controlled earning concepts</b><small>Gifts, vault access, promotion and creator rates are surfaced with clear controls; provider-dependent money movement is not represented as live.</small></div><div><span>04</span><b>Safety built into the flow</b><small>Verification concepts, reporting, blocking, privacy controls and date safety surfaces sit alongside engagement features.</small></div></div><div class="policy-card"><b>One-sentence pitch</b><p>Luma is designed to turn online matching into a richer connection platform where people can discover, communicate, date virtually and—where eligible—use creator-style tools without hiding the safety and infrastructure required to operate responsibly.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorVirtualDateSpotlight(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">VIRTUAL DATE SPOTLIGHT</div><h2>A guided date, not just another call</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">Virtual Dating gives matched adults a structured way to spend time together inside Luma before deciding what comes next.</p><div class="virtual-date-spotlight"><div><span>1</span><b>Choose the time</b><small>Start with a 15, 30 or 60 minute date format.</small></div><div><span>2</span><b>Pick the vibe</b><small>Conversation prompts, games, truth-or-dare style activities or a simple one-on-one date.</small></div><div><span>3</span><b>Extend together</b><small>If both people want more time, the date can move into an extension flow.</small></div><div><span>4</span><b>Private check-in</b><small>Afterward, each person can privately rate how it went and whether they would date again.</small></div></div><div class="virtual-date-proof-matrix" aria-label="Virtual Date lifecycle proof"><div><b>INVITE</b><small>Recipient consent is explicit; optional Truth or Dare consent can be withdrawn without cancelling the date.</small></div><div><b>ACTIVE</b><small>Either person can leave independently; added time requires mutual agreement.</small></div><div><b>SETTLE</b><small>Started minutes and unused whole minutes follow tested settlement rules.</small></div><div><b>FOLLOW-UP</b><small>Feedback stays private, and safety concerns override optional matching use.</small></div></div><div class="policy-card"><b>Investor distinction</b><p>The lifecycle and consent logic above is test-covered. Production live voice/video transport, billing, refunds, identity verification and provider enforcement still require real integrations and validation.</p></div><button class="primary" data-demo-date="nora">Open interactive Virtual Date</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}

function investorReadiness(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">DEMO READINESS</div><h2>What you can present today</h2></div><button class="icon-btn" data-close>×</button></div><div class="readiness-list"><div><span class="ready-dot"></span><p><b>Interactive product flows</b><small>Discovery, matches, messaging, profile controls and safety surfaces are available in Partner Demo.</small></p><strong>DEMO READY</strong></div><div><span class="ready-dot"></span><p><b>Virtual Dating</b><small>15/30/60-minute date concepts, activities, invitations, extensions and private post-date check-ins are represented.</small></p><strong>DEMO READY</strong></div><div><span class="ready-dot"></span><p><b>Monetization surfaces</b><small>Gifts, Top 30 promotion, vault pricing, creator rates and wallet concepts can be walked through.</small></p><strong>DEMO READY</strong></div><div class="provider-row"><span class="provider-dot"></span><p><b>External provider infrastructure</b><small>Payments, payouts, identity verification, live voice/video, push delivery and production signing still require provider credentials and production validation.</small></p><strong>NOT LIVE</strong></div></div><div class="policy-card"><b>Suggested investor path</b><p>Start with Discovery → open a Match → show Virtual Dating → return to the Investor Tour → finish with Business Model and Safety.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}

function investorRoadmap(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">LAUNCH ROADMAP</div><h2>From demo to production</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A transparent path for turning the current interactive product into a production launch without presenting unfinished infrastructure as complete.</p><div class="roadmap-list"><div class="done"><span>1</span><p><b>Product experience</b><small>Core discovery, matching, messaging, safety surfaces, monetization previews and structured Virtual Dating flows are represented in the interactive build.</small></p><strong>DEMO READY</strong></div><div><span>2</span><p><b>Provider integration</b><small>Connect and validate production payments, payouts, identity verification, voice/video transport and push delivery.</small></p><strong>REQUIRED</strong></div><div><span>3</span><p><b>Release hardening</b><small>Complete production environment configuration, legal URLs, security review, store assets, Android signing and device/store testing.</small></p><strong>REQUIRED</strong></div><div><span>4</span><p><b>Controlled launch</b><small>Begin with measured onboarding, safety monitoring, support operations and real product analytics before broader acquisition.</small></p><strong>NEXT</strong></div></div><div class="policy-card"><b>Investor takeaway</b><p>The product direction is demonstrable now; production readiness depends on completing and validating the external systems listed above.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorDemoScript(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">7-MINUTE INVESTOR DEMO</div><h2>A clean presentation path</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">Use this sequence to show the product quickly without presenting provider-dependent infrastructure as live.</p><div class="demo-script-list"><button data-demo-jump="discover"><span>01</span><p><b>Discovery + Top 30</b><small>Lead with curated connections, resonance and sponsored discovery.</small></p><strong>~60 sec</strong></button><button data-demo-open="virtual-date"><span>02</span><p><b>Virtual Dating</b><small>Show 15/30/60-minute dates, activities, mutual extensions and private check-ins.</small></p><strong>~150 sec</strong></button><button data-demo-jump="inbox"><span>03</span><p><b>Messaging</b><small>Show the path from a mutual connection into a private conversation.</small></p><strong>~45 sec</strong></button><button data-demo-open="business"><span>04</span><p><b>Business Model</b><small>Walk through gifts, promotion, vault concepts and platform revenue surfaces.</small></p><strong>~60 sec</strong></button><button data-demo-open="safety"><span>05</span><p><b>Safety + controls</b><small>Finish with reporting, blocking, privacy and account controls.</small></p><strong>~45 sec</strong></button><button data-demo-open="readiness"><span>06</span><p><b>Readiness</b><small>Close by separating interactive demo flows from external production dependencies.</small></p><strong>~60 sec</strong></button></div><div class="policy-card"><b>Presentation rule</b><p>Describe payments, payouts, identity verification, live voice/video, push delivery and signing as planned production integrations until real providers and credentials are connected and validated.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorRiskMoat(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">RISK + DEFENSIBILITY</div><h2>What Luma must prove—and what can compound</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">An investor-ready view of the hard parts, paired with the product advantages Luma is designed to strengthen over time.</p><div class="risk-moat-grid"><div><b>⚠ Trust + safety</b><small>Dating, creator tools and paid interactions require strong moderation, age/identity controls, reporting and careful policy enforcement.</small><strong>MITIGATION</strong><p>Verification gates, blocking/reporting, restricted-content controls and measurable moderation outcomes.</p></div><div><b>⚠ Provider dependency</b><small>Payments, payouts, voice/video and identity checks rely on approved production providers.</small><strong>MITIGATION</strong><p>Keep provider boundaries explicit, server-authoritative and replaceable rather than embedding fake completion into the client.</p></div><div><b>✦ Structured connection</b><small>Virtual Dating creates a product layer beyond swipe-and-chat: timed dates, activities, mutual extensions and private check-ins.</small><strong>POTENTIAL MOAT</strong><p>Better date outcomes can create proprietary product learning once real consented analytics exist.</p></div><div><b>✦ Multi-sided engagement</b><small>Discovery, Top 30 promotion, gifts, vault concepts and creator tools create multiple reasons to return.</small><strong>POTENTIAL MOAT</strong><p>A healthy network can compound through connection quality, creator participation and trusted reputation—not fabricated scale.</p></div></div><div class="policy-card"><b>What investors should hear</b><p>Luma’s defensibility is a thesis today, not a proven moat. Production traction, safety performance and retention must validate it.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorTractionPlan(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">EARLY TRACTION PLAN</div><h2>What Luma measures after launch</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">This is a measurement plan—not claimed traction. It gives an investor a concrete view of how product-market fit and safety would be evaluated once real users are onboarded.</p><div class="traction-grid"><div><b>Activation</b><strong>Profile → first meaningful connection</strong><small>Track completed profiles, discovery engagement and mutual matches.</small></div><div><b>Connection quality</b><strong>Match → conversation → date</strong><small>Measure conversations that progress into Virtual Date invitations and completed dates.</small></div><div><b>Retention</b><strong>Useful return behavior</strong><small>Monitor healthy repeat discovery, messaging and dating—not raw screen time alone.</small></div><div><b>Monetization</b><strong>Eligible paid actions</strong><small>Measure gifts, promotion, vault and creator-tool conversion only after compliant production billing exists.</small></div><div><b>Safety</b><strong>Reports + intervention</strong><small>Track report rates, blocks, moderation outcomes and response time alongside growth.</small></div><div><b>Unit economics</b><strong>Revenue vs. service cost</strong><small>Evaluate processor, moderation, support, infrastructure and acquisition costs against real net revenue.</small></div></div><div class="policy-card"><b>No fabricated numbers</b><p>Partner Demo intentionally does not display fake users, revenue, retention or conversion metrics. Real traction should be added only from validated production analytics.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorAskUse(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">PARTNER CONVERSATION</div><h2>What capital unlocks next</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A disciplined use-of-funds view for investor conversations. No funding amount, valuation, runway or launch date is claimed until a real financing plan and vendor quotes are approved.</p><div class="ask-use-grid"><div><b>01 · Production infrastructure</b><small>Transactional data, secure environments, monitoring, backups and operational tooling.</small></div><div><b>02 · Trust + safety</b><small>Identity/age provider integration, moderation operations, reporting workflows and policy enforcement.</small></div><div><b>03 · Payments + payouts</b><small>Approved processors, ledger reconciliation, fraud controls, settlement operations and compliance work.</small></div><div><b>04 · Live communication</b><small>Production voice/video provider integration, metering, reliability testing and abuse controls.</small></div><div><b>05 · Release hardening</b><small>Device QA, accessibility, performance, legal review, store readiness and production signing.</small></div><div><b>06 · Controlled growth</b><small>Measured acquisition and creator/community onboarding only after safety and unit economics can be observed.</small></div></div><div class="policy-card"><b>Investor-ready boundary</b><p>This screen explains priorities, not a promised budget. A formal raise should add an approved target, runway model, hiring plan and provider quotes before being presented as financial fact.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorProofMap(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">PRODUCT PROOF MAP</div><h2>What the demo proves—and what production still needs</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A fast diligence view across Luma’s major product surfaces, with demo evidence separated from external infrastructure.</p><div class="proof-map-grid"><button data-demo-jump="discover"><b>Discovery + matching</b><small>Interactive cards, filters, Top 30 placement and mutual-match paths.</small><strong>DEMO READY</strong></button><button data-demo-open="virtual-date"><b>Virtual Dating</b><small>15/30/60-minute formats, activities, invitations, extensions and private check-ins.</small><strong>DEMO READY</strong></button><button data-demo-jump="inbox"><b>Messaging</b><small>Interactive conversation UI, prompts, gifts entry and safety controls.</small><strong>DEMO READY</strong></button><button data-demo-open="safety"><b>Safety + privacy</b><small>Reporting, blocking, meeting-safety and account-control surfaces.</small><strong>DEMO READY</strong></button><div class="provider"><b>Money movement</b><small>Wallet, gifts, vault pricing and cash-out concepts exist; real processing and payouts require approved providers and credentials.</small><strong>PROVIDER REQUIRED</strong></div><div class="provider"><b>Identity + live communication</b><small>Verification and call/video concepts exist; production identity checks, media transport and push delivery are not connected.</small><strong>PROVIDER REQUIRED</strong></div></div><div class="policy-card"><b>Diligence rule</b><p>Interactive product behavior is evidence of the current demo. It is not evidence of processor approval, identity-provider verification, completed payouts, live call transport, push delivery or production signing.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorFAQ(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">INVESTOR FAQ</div><h2>Fast answers to diligence questions</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A concise, presentation-safe view of the questions most likely to come up after the product walkthrough.</p><div class="investor-faq"><div><b>What is the wedge?</b><p>Structured connection: discovery can progress into guided 15/30/60-minute Virtual Dates instead of stopping at swipe-and-chat.</p></div><div><b>How can Luma earn?</b><p>Planned surfaces include gifts, Top 30 promotion, vault access and creator communication tools. Real billing and payouts require approved production providers.</p></div><div><b>What is working in this build?</b><p>Interactive discovery, matches, messaging, Virtual Date flows, invitations, extensions, private check-ins and safety/account-control surfaces.</p></div><div><b>What is not live?</b><p>Real payments, payouts, identity verification, live voice/video transport, push delivery and production signing are not production-ready without credentials and provider validation.</p></div><div><b>What must be proven after launch?</b><p>Activation, connection quality, retention, safe monetization, moderation performance and unit economics using validated production analytics.</p></div><div><b>What is the next technical milestone?</b><p>Replace simulated/provider-dependent paths with production integrations, transactional storage, signed release builds and end-to-end release validation.</p></div></div><div class="policy-card"><b>Presentation-safe answer</b><p>This demo proves product direction and interactive behavior; it does not prove processor approval, verified identity coverage, completed payouts, live media transport or production scale.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorVirtualDateLifecycle(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">VIRTUAL DATE LIFECYCLE</div><h2>Designed around consent, time and clear settlement</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A diligence view of how Luma’s structured Virtual Dating concept moves from invitation to private follow-up.</p><div class="virtual-date-lifecycle"><div><span>01</span><b>Invite + accept</b><small>A matched adult proposes 15, 30 or 60 minutes and the other person accepts before a date starts.</small></div><div><span>02</span><b>Structured time</b><small>The date can use prompts, games or simple one-on-one conversation while the selected duration stays explicit.</small></div><div><span>03</span><b>Exit without trapping time</b><small>If a participant exits early, unused purchased minutes are designed to return to the purchaser under Luma’s settlement rules.</small></div><div><span>04</span><b>Mutual extension</b><small>Extra time is a separate choice: both participants must agree before an extension proceeds.</small></div><div><span>05</span><b>Private check-in</b><small>After the date, each participant can privately rate the experience and whether they would date again.</small></div><div><span>06</span><b>Safety + records</b><small>Exit, report and block paths remain available; production auditability depends on transactional storage and provider event validation.</small></div></div><div class="policy-card"><b>What is proven here</b><p>The current build demonstrates lifecycle and settlement logic. Real billing, refunds, live media transport, identity verification and provider event enforcement still require production integrations and credentials.</p></div><button class="primary" data-demo-date="nora">Open interactive Virtual Date</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorDemoHandoff(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">INVESTOR HANDOFF</div><h2>What to remember after the demo</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A concise close for the presentation: product proof, Virtual Dating differentiation, and the exact boundary between demo behavior and production infrastructure.</p><div class="handoff-grid"><div><span>01</span><b>Product proof</b><small>Discovery, matching, messaging, safety surfaces and the guided Partner Demo are interactive today.</small></div><div><span>02</span><b>Virtual Dating wedge</b><small>15/30/60-minute dates add explicit duration, activities, mutual extensions, early-exit settlement logic and private check-ins.</small></div><div><span>03</span><b>Monetization thesis</b><small>Gifts, Top 30, vaults and creator tools are product concepts; real money movement still requires approved providers and production validation.</small></div><div><span>04</span><b>Next proof point</b><small>Connect provider-backed infrastructure, transactional storage and signed releases, then measure real activation, retention, safety and unit economics.</small></div></div><div class="policy-card"><b>Safe closing line</b><p>Luma has an interactive product direction and a differentiated structured-dating system. Payments, payouts, identity verification, live voice/video, push delivery and signing are not production-ready until real credentials, providers and end-to-end validation are complete.</p></div><button class="primary" data-demo-open="date-lifecycle">Revisit Virtual Date lifecycle</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorEvidenceChecklist(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">DEMO EVIDENCE CHECKLIST</div><h2>Show it, then state exactly what it proves</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A presentation-safe checklist that ties investor claims to interactive product evidence while keeping external infrastructure claims out of scope.</p><div class="evidence-checklist"><button data-demo-jump="discover"><span>✓</span><p><b>Discovery + Top 30</b><small>Show cards, filters and promoted discovery. Proves an interactive discovery concept—not acquisition or ranking performance.</small></p></button><button data-demo-jump="inbox"><span>✓</span><p><b>Messaging</b><small>Show the seeded conversation and safety entry points. Proves UI behavior—not production message delivery or push.</small></p></button><button data-demo-open="date-lifecycle"><span>✓</span><p><b>Virtual Dating</b><small>Show 15/30/60-minute structure, mutual extensions, early-exit settlement rules and private check-ins. Proves product and tested settlement logic—not live media or real refunds.</small></p></button><button data-demo-open="safety"><span>✓</span><p><b>Safety controls</b><small>Show report, block and meeting-safety surfaces. Proves product controls—not production moderation staffing or identity-provider enforcement.</small></p></button></div><div class="provider-boundary"><b>Provider boundary</b><p>Payments, payouts, identity verification, live voice/video transport, push delivery and signed production releases remain unverified until real credentials, providers and end-to-end production validation are complete.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorVirtualDateTrustModel(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">VIRTUAL DATE TRUST MODEL</div><h2>Consent gates before, during and after a date</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A product-level view of the controls designed to keep structured dates voluntary and auditable without pretending provider infrastructure is already live.</p><div class="trust-model-grid"><div><span>BEFORE</span><b>Mutual participation</b><small>A date begins only after an invitation is accepted. Duration stays explicit at 15, 30 or 60 minutes.</small></div><div><span>DURING</span><b>Exit remains available</b><small>Either participant can leave; unused purchased minutes follow Luma’s settlement rules instead of trapping the purchaser in unused time.</small></div><div><span>EXTEND</span><b>No one-sided extension</b><small>Additional time requires both participants to agree. A single request does not silently extend the session.</small></div><div><span>SAFETY</span><b>Block + report paths</b><small>Safety actions remain available around the date experience and are designed to interrupt future contact when needed.</small></div><div><span>AFTER</span><b>Private feedback</b><small>Post-date check-ins are private product signals, including whether someone would choose another date.</small></div><div><span>PRODUCTION</span><b>Server authority required</b><small>Real billing, refunds, identity status, media sessions and provider events must be enforced by transactional backend systems—not client state.</small></div></div><div class="provider-boundary"><b>Release boundary</b><p>The demo can prove these product rules and tested client/server logic. Production enforcement still depends on real provider credentials, transactional storage, authenticated events and end-to-end validation.</p></div><button class="primary" data-demo-open="date-lifecycle">Open lifecycle view</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorTechnicalDiligence(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">TECHNICAL DILIGENCE</div><h2>What is built, tested, and still gated</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A presentation-safe engineering view for an investor or technical advisor. It separates product logic already covered by automated checks from infrastructure that cannot be called production-ready yet.</p><div class="diligence-grid"><div><span>TESTED PRODUCT LOGIC</span><b>Virtual Dating rules</b><small>Automated coverage includes invitations, 15/30/60-minute date configuration, mutual extensions, exits, settlement math, notices, private check-ins and feedback.</small></div><div><span>TESTED SAFETY + ACCOUNT</span><b>Release guardrails</b><small>Automated checks cover browser/client safety, account registration/login/session/deletion, age discovery rules, storage safeguards and Android backup protection.</small></div><div><span>PACKAGING</span><b>Web ↔ Android parity</b><small>The release workflow verifies that packaged Android web assets match the rebuilt web output before a checkpoint is called verified.</small></div><div class="gated"><span>PROVIDER GATED</span><b>External systems remain blocked</b><small>Real payments, payouts, identity verification, live voice/video, push delivery and production signing require credentials, provider wiring and end-to-end validation.</small></div></div><div class="provider-boundary"><b>Engineering claim boundary</b><p>Passing product tests demonstrates the behavior under test. It does not certify processor approval, provider uptime, real-money settlement, verified identity, live-media quality, store approval or a signed production release.</p></div><button class="primary" data-demo-open="date-trust">Review Virtual Date trust model</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}

function investorPrivateFeedbackProof(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">PRIVATE FEEDBACK PROOF</div><h2>Useful matching signals without a popularity score</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">Luma’s post-date check-in is designed to improve safety, quality and future matching without turning people into public ratings.</p><div class="trust-model-grid"><div><span>PRIVATE INPUT</span><b>1–5 date rating</b><small>Each participant can privately describe how the date went after eligible date activity.</small></div><div><span>INTENT SIGNAL</span><b>Would date again</b><small>A private yes/no signal can help matching quality without exposing rejection or approval to the other participant.</small></div><div><span>NO LEADERBOARD</span><b>No public attractiveness score</b><small>Ratings are not designed for profile badges, popularity rankings, public averages or search ordering based on desirability.</small></div><div><span>ABUSE BOUNDARY</span><b>Safety signals stay separate</b><small>Reports, blocks and moderation evidence must not be collapsed into a public reputation number.</small></div><div><span>MINIMIZATION</span><b>Only eligible feedback</b><small>Feedback should be accepted only for the authenticated participant and eligible completed date, with duplicate submission prevented.</small></div><div><span>PRODUCTION</span><b>Server authority required</b><small>Durable feedback, abuse controls and matching use require authenticated production storage, access controls and privacy review.</small></div></div><div class="provider-boundary"><b>Investor claim boundary</b><p>The current build demonstrates and tests private feedback behavior. It does not prove production analytics, moderation operations, durable provider-backed storage or a validated matching model.</p></div><button class="primary" data-demo-open="date-story">Open Virtual Date investor story</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorActiveDateSafetyProof(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">ACTIVE DATE SAFETY PROOF</div><h2>A participant keeps an independent way out</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">Virtual Dating safety is designed so a participant can record leave intent from their own authenticated account even when a provider heartbeat is stale or the other profile has been blocked.</p><div class="trust-model-grid"><div><span>PRIVATE DISCOVERY</span><b>Only your active-date state</b><small>The safety lookup exposes no partner, match, invitation, provider-session or ledger identifiers.</small></div><div><span>INDEPENDENT EXIT</span><b>Leave intent does not require partner approval</b><small>A participant can record their own exit intent without waiting for the other person to respond.</small></div><div><span>BLOCK RESILIENT</span><b>Safety remains reachable</b><small>Blocking a profile does not remove the participant’s ability to record exit intent for an already-active date.</small></div><div><span>TEST COVERED</span><b>Backend + client behavior</b><small>Automated integration coverage checks privacy, stale connections, blocked profiles and the provider/refund claim boundary.</small></div></div><div class="provider-boundary"><b>Production boundary</b><p>Recording leave intent does not prove that a live-media provider disconnected the session or that money was refunded. Those actions require authenticated provider events, transactional settlement and real production credentials.</p></div><button class="primary" data-demo-open="date-trust">Review Virtual Date trust model</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorVirtualDateEconomics(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">VIRTUAL DATE ECONOMICS</div><h2>How structured dates can become measurable economics</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A diligence framework—not a revenue forecast. It shows the inputs Luma would measure once approved billing, payouts and real production usage exist.</p><div class="date-economics-grid"><div><span>DEMAND</span><b>Date starts</b><small>Accepted invitations that progress into 15, 30 or 60-minute sessions.</small></div><div><span>DEPTH</span><b>Minutes completed</b><small>Purchased time actually used, including mutually accepted extensions.</small></div><div><span>SETTLEMENT</span><b>Unused time</b><small>Early exits must reconcile unused purchased minutes under Luma’s settlement rules before net revenue is recognized.</small></div><div><span>CREATOR SIDE</span><b>Eligible earnings</b><small>Where paid communication is permitted, creator earnings and platform share require provider-backed ledger entries and payout eligibility.</small></div><div><span>COST TO SERVE</span><b>Media + trust costs</b><small>Live-media transport, moderation, identity checks, support, processor fees and fraud losses affect contribution margin.</small></div><div><span>QUALITY</span><b>Healthy repeat use</b><small>Repeat dates, private feedback and safety outcomes matter alongside monetization; raw minutes alone are not the success metric.</small></div></div><div class="provider-boundary"><b>No invented economics</b><p>This build does not claim ARPU, take rate, gross margin, conversion, payout volume or date revenue. Those figures require approved pricing, real processor settlement, provider invoices and validated production analytics.</p></div><button class="primary" data-demo-open="date-lifecycle">Review Virtual Date lifecycle</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorReleaseGates(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">RELEASE GATE MATRIX</div><h2>What must turn green before launch</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A release-readiness view that keeps investor presentation claims separate from production approval.</p><div class="release-gate-grid"><div class="ready"><span>VERIFIED IN BUILD</span><b>Product logic + demo</b><small>Discovery, matching, messaging surfaces, safety controls and Virtual Date rules have automated coverage in this checkpoint.</small></div><div class="ready"><span>VERIFIED IN BUILD</span><b>Packaging parity</b><small>Rebuilt web assets are checked against the Android packaged web assets before the checkpoint is marked verified.</small></div><div class="gated"><span>PROVIDER REQUIRED</span><b>Money movement</b><small>Approved payment, RevenueCat and payout credentials plus provider-backed ledger and settlement validation.</small></div><div class="gated"><span>PROVIDER REQUIRED</span><b>Trust + live media</b><small>Identity/age verification, media scanning and live voice/video require real providers, credentials and end-to-end testing.</small></div><div class="gated"><span>RELEASE REQUIRED</span><b>Store + legal</b><small>Production origins, public legal/support URLs, Android signing and store release validation must be completed.</small></div><div class="gated"><span>BACKEND REQUIRED</span><b>Authoritative events</b><small>Virtual Date billing/refunds, messaging/moderation events and payout state must be enforced transactionally on trusted backend systems.</small></div></div><div class="provider-boundary"><b>Launch rule</b><p>Luma is not production-ready until every provider, backend, legal and signing gate required by the release preflight is configured and verified end to end.</p></div><button class="primary" data-demo-open="diligence">Open technical diligence</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}

function investorDemoRunbook(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">INVESTOR DEMO RUNBOOK</div><h2>A clean 7-minute presentation path</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">Use this sequence to show the product before discussing infrastructure. Each stop pairs a visible Luma experience with the claim it can safely support.</p><div class="runbook-coverage" aria-label="Partner Demo coverage"><b>7-minute coverage</b><span>Discovery</span><span>Messaging</span><span class="focus">Virtual Dating · 2½ min</span><span>Safety</span><span>Monetization</span><span>Release gates</span><small>Virtual Dating receives the largest share of the presentation while every major investor question gets a concrete product stop.</small></div><div class="runbook-evidence-legend" aria-label="Investor evidence legend"><b>Evidence key</b><span class="interactive">INTERACTIVE · visible in demo</span><span class="tested">TESTED · automated behavior checks</span><span class="gated">GATED · external provider required</span><small>Use this key while presenting: interactive and tested describe this persisted product build; gated items are not production claims.</small></div><div class="runbook-grid"><div><span>0:00–1:00</span><b>Discovery + Top 30</b><small>Show curated signals, resonance and sponsored discovery. Position Top 30 as a promotion concept—not proven revenue.</small><button class="runbook-action" data-demo-jump="discover">Open Discovery</button></div><div><span>1:00–2:00</span><b>Match + message</b><small>Open a match and conversation to show the path from discovery into a private connection.</small><button class="runbook-action" data-demo-chat="nora">Open seeded conversation</button></div><div class="runbook-feature"><span>2:00–4:30</span><b>Virtual Dating</b><small>Lead with 15/30/60-minute dates, activities, mutual extensions, voluntary exit, unused-time settlement rules and private follow-up.</small><button class="runbook-action" data-demo-date="nora">Open interactive Virtual Date</button></div><div><span>4:30–5:15</span><b>Safety + trust</b><small>Show report/block and explain that real identity verification and moderation infrastructure remain provider-gated.</small><button class="runbook-action" data-demo-open="safety">Open Safety Center</button></div><div><span>5:15–6:00</span><b>Creator + wallet concepts</b><small>Show monetization surfaces while clearly labeling balances, calling and payouts as preview behavior.</small><button class="runbook-action" data-demo-open="wallet">Open Wallet preview</button></div><div><span>6:00–7:00</span><b>Proof + release gates</b><small>Close with automated coverage, checkpoint integrity and the provider/backend/legal/signing work still required.</small><button class="runbook-action" data-demo-open="release-gates">Open Release Gates</button></div></div><div class="policy-card runbook-close"><b>30-second close</b><p><strong>Problem:</strong> matching apps often stop at chat. <strong>Luma:</strong> turns a match into a structured 15/30/60-minute Virtual Date with explicit consent, mutual extensions, voluntary exit and private follow-up. <strong>Business:</strong> gifts, promotion, vault and creator surfaces create multiple monetization paths. <strong>Next proof:</strong> connect approved providers and transactional infrastructure, then measure activation, retention, safety and unit economics.</p></div><div class="runbook-proof-plan"><b>Post-pilot proof plan</b><div><span>ACTIVATION</span><small>Match → Virtual Date invitation → accepted date conversion.</small></div><div><span>QUALITY</span><small>Date completion, mutual extension and private would-date-again signals.</small></div><div><span>SAFETY</span><small>Exit, block/report and moderation rates by completed date.</small></div><div><span>ECONOMICS</span><small>Provider cost, settlement/refund behavior and contribution margin only after real billing exists.</small></div><p>No traction or revenue is implied here; these are the measurements Luma should collect after a real pilot is instrumented.</p></div><div class="runbook-investor-questions" aria-label="Investor discussion prompts"><b>Turn the demo into a discussion</b><p>After the walkthrough, use these prompts to learn what would move an investor from interest to diligence.</p><div><span>PROOF</span><small>Which next milestone would most increase your conviction: activation, retention, safety performance, or unit economics?</small></div><div><span>DISTRIBUTION</span><small>Which early user segment or acquisition channel would you pressure-test first?</small></div><div><span>RISK</span><small>Which provider, moderation, compliance, or marketplace risk would you want de-risked before a pilot?</small></div><div><span>PILOT</span><small>What evidence would you expect from a controlled Virtual Dating pilot before a larger raise?</small></div><button class="runbook-action" data-demo-open="faq">Open investor FAQ</button></div><div class="runbook-decision-lens" aria-label="Investor decision lens"><b>Decision lens</b><p>End with a concrete next-step frame instead of an unsupported valuation or traction claim.</p><div><span>WHAT EXISTS</span><small>Interactive discovery, messaging, safety surfaces and tested Virtual Dating product logic.</small></div><div><span>WHAT TO PROVE</span><small>Real pilot activation, date quality, safety outcomes, retention and provider-backed unit economics.</small></div><div><span>WHAT CAPITAL UNLOCKS</span><small>Provider integrations, authoritative backend enforcement, moderation operations, legal readiness and signed release work.</small></div><div><span>WHAT NOT TO CLAIM</span><small>No booked revenue, processor approval, verified identity population, live-media infrastructure or production payouts are implied by this demo.</small></div></div><div class="runbook-capital-map" aria-label="Capital deployment map"><b>Capital deployment map</b><p>Keep the investment conversation tied to verifiable release work rather than unsupported forecasts.</p><div><span>PROVIDER LAYER</span><small>Connect and verify approved payments, payouts, identity, live media and push providers with real credentials.</small></div><div><span>BACKEND + SAFETY</span><small>Move money, settlement, moderation and provider-event authority into transactional production systems.</small></div><div><span>RELEASE READINESS</span><small>Complete legal/support endpoints, production origins, Android signing, observability and release evidence.</small></div><div><span>PILOT LEARNING</span><small>Instrument Virtual Dating activation, quality, safety, retention and provider-backed unit economics before making traction claims.</small></div><p class="muted">No funding amount, valuation, runway, revenue or provider approval is asserted by this demo.</p></div><div class="runbook-recovery" aria-label="Presenter recovery path"><b>Presenter recovery path</b><p>If a live walkthrough gets interrupted, recover without changing the claim: reset the seeded Partner Demo, reopen the Investor Runbook, and return to the Virtual Dating centerpiece.</p><div><span>1</span><small>Use <strong>Reset demo</strong> to restore the seeded presentation state.</small></div><div><span>2</span><small>Use <strong>Start 7-min demo</strong> to reopen the timed runbook.</small></div><div><span>3</span><small>Use <strong>Start with Virtual Dating</strong> to resume the strongest interactive proof point.</small></div><p class="muted">Recovery changes demo state only; it does not create provider connectivity, transactions, verification, live media or production readiness.</p></div><div class="provider-boundary"><b>Presentation rule</b><p>Show working product behavior first. Never present demo credits, simulated calls, preview verification, payout screens or automated tests as evidence that an external provider is live or approved.</p></div><button class="primary" data-demo-open="virtual-date">Start with Virtual Dating</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorExtensionConsentProof(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">EXTENSION CONSENT PROOF</div><h2>More time requires two explicit yeses</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">Luma’s Virtual Dating extension flow is designed so one participant can propose more time, but only the other participant can accept or decline the proposal.</p><div class="trust-model-grid"><div><span>PROPOSE</span><b>15, 30 or 60 more minutes</b><small>The requester chooses an allowed extension and receives a server-generated quote.</small></div><div><span>CONSENT</span><b>Recipient-only decision</b><small>The requester cannot approve their own proposal; the other participant must explicitly agree.</small></div><div><span>PRIVACY</span><b>Capability-based response</b><small>Client responses use proposedByYou and canRespond rather than exposing participant account identifiers.</small></div><div><span>IDEMPOTENT</span><b>Repeat-safe decisions</b><small>Automated backend coverage protects mutual-consent behavior from duplicate agreement requests.</small></div><div><span>REVOCABLE</span><b>Consent can be withdrawn before execution</b><small>A pending proposal can be withdrawn, and stored mutual consent can be cancelled while no provider time or payment hold has been applied.</small></div><div><span>FAIL CLOSED</span><b>Provider/payment state wins</b><small>If provider time or a payment hold is already recorded, cancellation is refused until verified disconnect and settlement handling can run.</small></div></div><div class="provider-boundary"><b>Production boundary</b><p>Agreement records product consent only. It does not hold funds, charge either participant, extend a live-media session, or prove provider acceptance. Those actions require authenticated provider events, transactional settlement and real production credentials.</p></div><button class="primary" data-demo-open="date-lifecycle">Review full Virtual Date lifecycle</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}

function investorVirtualDateConsentProof(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">VIRTUAL DATE CONSENT PROOF</div><h2>Consent stays specific, reversible and private</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A diligence view of the consent boundaries already represented in Luma’s Virtual Dating product logic.</p><div class="checkpoint-grid"><div class="ready"><span>INVITATION</span><b>Explicit agreement</b><small>A recipient chooses whether to accept a quoted 15, 30 or 60 minute invitation; silence is not consent.</small></div><div class="ready"><span>TRUTH OR DARE</span><b>Separate, revocable opt-in</b><small>Truth or Dare requires its own affirmative checkbox, can be withdrawn without cancelling the date, and every prompt remains optional and skippable.</small></div><div class="ready"><span>EXTENSIONS</span><b>Mutual only</b><small>Extra time requires a new agreement rather than treating the original date consent as permission to continue.</small></div><div class="ready"><span>EARLY EXIT</span><b>Independent leave</b><small>Either participant can record leave intent without partner approval; unused-time handling follows settlement rules.</small></div><div class="ready"><span>POST-DATE</span><b>Private feedback</b><small>1–5 ratings and date-again answers stay private and cannot become a public attractiveness or popularity score.</small></div><div class="gated"><span>PRODUCTION ENFORCEMENT</span><b>Provider-backed proof required</b><small>Live-media disconnect, real refunds or credits, identity checks and durable audit storage require verified production providers and transactional infrastructure.</small></div></div><div class="provider-boundary"><b>Consent rule</b><p>One consent never authorizes another action. Date acceptance, Truth or Dare, extensions, feedback use and provider-side execution remain separate decisions and gates.</p></div><button class="primary" data-demo-date="nora">Open interactive Virtual Date</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorDemoHealth(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">PARTNER DEMO HEALTH</div><h2>What is safe to demonstrate right now</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A presentation control panel for keeping the investor walkthrough focused on verified product behavior while making production dependencies unmistakable.</p><div class="demo-health-grid"><div class="ready"><span>INTERACTIVE</span><b>Core product journey</b><small>Discovery, matches, messaging, profile controls and safety surfaces are available for the Partner Demo.</small></div><div class="ready"><span>INTERACTIVE + TESTED</span><b>Virtual Dating</b><small>15/30/60-minute setup, optional activities, invitation consent, mutual extensions, voluntary exit, unused-time settlement rules and private follow-up are represented and test-covered.</small></div><div class="ready"><span>CHECKPOINT EVIDENCE</span><b>Package integrity</b><small>Source fingerprints, checkpoint lineage and web-to-Android asset parity are automated release gates for this demo package.</small></div><div class="gated"><span>EXTERNAL PROVIDERS</span><b>Do not present as live</b><small>Payments, payouts, identity verification, live voice/video, push delivery, media scanning and signing require real credentials and end-to-end validation.</small></div><div class="gated"><span>PRODUCTION BACKEND</span><b>Still release-gated</b><small>Transactional storage, authenticated provider events, durable audit evidence, production origins and moderation operations remain required.</small></div><div class="gated"><span>LEGAL + STORE</span><b>Still release-gated</b><small>Public privacy/terms/delete/support URLs, signed Android release validation, physical-device testing and Google Play review remain unfinished.</small></div></div><div class="provider-boundary"><b>Presenter guardrail</b><p>Show interactive behavior as product evidence. Describe every external integration as planned or gated until real credentials, provider responses and production validation exist.</p></div><button class="primary" data-demo-open="runbook">Start investor runbook</button><button class="secondary" data-demo-open="release-gates">Review release gates</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorVirtualDateStory(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">VIRTUAL DATE INVESTOR STORY</div><h2>From match to meaningful signal</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A concise product story investors can follow in under two minutes. Each step maps to Luma behavior already represented in this checkpoint, while provider-dependent execution stays explicitly gated.</p><div class="date-story"><div><span>01</span><b>Choose the commitment</b><small>Start with a private 15, 30 or 60 minute date for Real Love or Friendship.</small></div><div><span>02</span><b>Make it easier to connect</b><small>Use optional games, conversation questions, planned mini-dates or separately opted-in Truth or Dare. Every activity can be skipped.</small></div><div><span>03</span><b>Stay only by mutual choice</b><small>Extensions require both people to agree. Either participant can leave independently at any time.</small></div><div><span>04</span><b>Handle unused time fairly</b><small>Early-exit settlement logic calculates unused prepaid time; a real refund or credit still requires transactional provider-backed execution.</small></div><div><span>05</span><b>Learn privately</b><small>Each participant can privately rate the date 1–5 and answer whether they would date again. Feedback is not a public attractiveness or popularity score.</small></div></div><div class="provider-boundary"><b>Investor takeaway</b><p>Luma’s differentiation is the structured path between matching and a real decision to keep connecting. This build demonstrates the product rules; it does not claim live media, payment/refund execution, identity verification or provider approval.</p></div><button class="primary" data-demo-date="nora">Open interactive Virtual Date</button><button class="secondary" data-demo-open="feedback-governance">Review private feedback safeguards</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorVerifiedCheckpoint(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">VERIFIED CHECKPOINT</div><h2>${CHECKPOINT_VERSION} · evidence-backed demo status</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A compact diligence snapshot tied to the persisted checkpoint. It distinguishes automated product verification from production-provider approval.</p><div class="checkpoint-grid"><div class="ready"><span>CHECKPOINT</span><b>${CHECKPOINT_VERSION} from ${CHECKPOINT_BASE_VERSION}</b><small>Persisted lineage is validated by the checkpoint-integrity gate.</small></div><div class="ready"><span>PRIVATE FEEDBACK</span><b>Safety overrides matching consent</b><small>Selecting any safety concern clears optional matching use on the client and server, while routing the concern privately to moderation.</small></div><div class="ready"><span>ANDROID RELEASE</span><b>Release signing guard</b><small>Release tasks require complete secret-backed signing and never fall back to a debug key; real signed-AAB validation remains gated.</small></div><div class="ready"><span>PACKAGE</span><b>Web ↔ Android parity</b><small>Rebuilt web assets must match packaged Android assets before this checkpoint is marked verified.</small></div><div class="ready"><span>SOURCE INTEGRITY</span><b>Core fingerprints</b><small>Critical source and test files are SHA-256 fingerprinted so checkpoint drift is detected.</small></div><div class="ready"><span>ANDROID PERMISSIONS</span><b>Permission minimization</b><small>Android packages network access only; camera, microphone, location and notification permissions stay absent until their provider-backed features and runtime consent flows are implemented and reviewed.</small></div><div class="gated"><span>PRODUCTION GATED</span><b>External providers</b><small>Payments, payouts, identity verification, live voice/video, push and signing remain blocked until real credentials and end-to-end validation exist.</small></div><div class="gated"><span>RELEASE GATED</span><b>Backend + legal</b><small>Transactional production storage, authenticated provider events, production origins and public legal/support URLs remain required.</small></div></div><div class="provider-boundary"><b>Evidence rule</b><p>A verified checkpoint means the persisted code passed its stated automated gates. It does not mean Luma is production-ready or that any external provider has approved or processed a real transaction.</p></div><button class="primary" data-demo-open="release-gates">Review release gates</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorVirtualDatePilotScorecard(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">VIRTUAL DATE PILOT SCORECARD</div><h2>What a controlled pilot must prove</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A measurement plan for Real Love and Friendship—not fabricated traction. Each signal becomes reportable only after consented production analytics and provider-backed events exist.</p><div class="date-economics-grid"><div><span>ACTIVATION</span><b>Invitation → accepted date</b><small>Measure how often eligible matches choose a 15, 30 or 60-minute structured date.</small></div><div><span>QUALITY</span><b>Healthy completion</b><small>Track completed dates and mutually agreed extensions without turning private ratings into a public popularity score.</small></div><div><span>FAIRNESS</span><b>Early-exit settlement</b><small>Reconcile unused prepaid time from verified attendance and exit events before reporting settlement performance.</small></div><div><span>SAFETY</span><b>Reports + independent exits</b><small>Measure safety events, response handling and exit accessibility while minimizing sensitive-data exposure.</small></div><div><span>RETENTION</span><b>Would-date-again signal</b><small>Use private post-date intent as a protected matching/quality input, never a public attractiveness score.</small></div><div><span>ECONOMICS</span><b>Provider-backed unit inputs</b><small>Only calculate paid conversion, processor cost and contribution after real billing, refunds and provider invoices are reconciled.</small></div></div><div class="provider-boundary"><b>Pilot evidence boundary</b><p>This checkpoint defines what to measure; it does not claim users, conversion, revenue, refunds, provider approval or production analytics. Payments, payouts, identity verification, live media and push remain provider-gated.</p></div><button class="primary" data-demo-open="date-lifecycle">Review Virtual Date lifecycle</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorProviderBoundaryMap(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">PROVIDER BOUNDARY MAP</div><h2>What Luma owns vs. what providers must prove</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">Use this diligence view to separate tested Luma product behavior from external systems that require real credentials, contracts and end-to-end validation.</p><div class="provider-boundary-map"><div class="ready"><span>LUMA-OWNED · TESTED</span><b>Virtual Date product rules</b><small>15/30/60-minute configuration, invitation consent, mutual extensions, voluntary exit, settlement math, private notices and private post-date check-ins.</small></div><div class="ready"><span>LUMA-OWNED · TESTED</span><b>Safety + presentation boundaries</b><small>Report/block surfaces, active-date exit intent, account controls, demo-credit labeling, checkpoint integrity and web/Android asset parity.</small></div><div class="gated"><span>PROVIDER-GATED</span><b>Money movement</b><small>Real charges, RevenueCat/store purchase validation, refunds, creator payouts and bank settlement require approved providers plus authoritative ledger events.</small></div><div class="gated"><span>PROVIDER-GATED</span><b>Trust + communication</b><small>Identity/age verification, secure media scanning, live voice/video transport and push delivery require real provider credentials and verified callbacks.</small></div><div class="gated"><span>RELEASE-GATED</span><b>Production distribution</b><small>Production origins, public legal/support URLs, Android signing, device testing and Google Play review remain release requirements.</small></div><div class="gated"><span>BACKEND-GATED</span><b>Authoritative state</b><small>Production sessions, transactional storage, provider event authentication, moderation operations and settlement enforcement must live on trusted infrastructure.</small></div></div><div class="provider-boundary"><b>Investor-safe claim</b><p>This checkpoint demonstrates tested product logic and an investor-presentable experience. It does not prove processor approval, real-money movement, verified identities, live-media delivery, push delivery, signed production binaries or store approval.</p></div><button class="primary" data-demo-open="release-gates">Open Release Gate Matrix</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}

function investorFeedbackGovernance(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">PRIVATE FEEDBACK GOVERNANCE</div><h2>Quality signals without a popularity score</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">Luma’s post-date 1–5 rating and “date again” answer are designed as private safety, quality and matching inputs—not public social proof.</p><div class="trust-model-grid"><div><span>PRIVATE BY DEFAULT</span><b>No public score</b><small>Ratings and would-date-again answers are not shown on profiles, leaderboards or popularity rankings.</small></div><div><span>MINIMUM DISCLOSURE</span><b>No partner reveal</b><small>A participant does not receive the other person’s private rating or date-again answer.</small></div><div><span>ABUSE RESISTANCE</span><b>Separate safety reporting</b><small>Blocks and reports stay independent from the 1–5 quality signal so safety concerns are not reduced to a low rating.</small></div><div><span>MATCHING SIGNAL</span><b>Use with context</b><small>Private feedback may inform future quality and matching systems only with anti-retaliation, access-control and retention safeguards.</small></div><div><span>ANALYTICS</span><b>Aggregate carefully</b><small>Investor and operations reporting should use privacy-preserving aggregates, not expose individual attractiveness or popularity.</small></div><div><span>PRODUCTION GATE</span><b>Policy + storage required</b><small>Production use requires transactional access controls, retention/deletion policy, moderation review rules and privacy/legal approval.</small></div></div><div class="provider-boundary"><b>Investor claim boundary</b><p>This build demonstrates the intended feedback-governance model and tested private check-in behavior. It does not claim a production recommendation model, moderation operation, privacy approval or live analytics pipeline.</p></div><button class="primary" data-demo-open="date-trust">Review Virtual Date trust model</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}

function investorActivitySafety(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">VIRTUAL DATE ACTIVITIES</div><h2>Fun by choice, never by pressure</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">Built-in games, conversation questions, mini-date activities and Truth or Dare are optional layers inside a private 1-on-1 Virtual Date. Either participant can skip an activity without ending the date.</p><div class="trust-model-grid"><div><span>OPTIONAL</span><b>Games</b><small>Light cooperative or playful prompts can reduce first-date awkwardness without becoming a participation requirement.</small></div><div><span>LOW PRESSURE</span><b>Conversation questions</b><small>Prompt decks support Real Love and Friendship conversations, with a visible skip path for either participant.</small></div><div><span>PLANNED</span><b>Mini-date activities</b><small>Shared themes can structure the time while preserving each participant’s independent ability to leave.</small></div><div><span>CONSENT FIRST</span><b>Truth or Dare</b><small>Truth or Dare is opt-in, skippable and must not be used to pressure sexual, financial, dangerous, illegal or off-platform behavior.</small></div><div><span>SAFETY</span><b>Report stays separate</b><small>Skipping a prompt does not penalize matching or feedback. Report, block and voluntary exit remain available independently.</small></div><div><span>PRODUCTION GATE</span><b>Moderation required</b><small>Dynamic or user-generated activity content requires production moderation, policy enforcement and abuse monitoring before launch.</small></div></div><div class="provider-boundary"><b>Investor claim boundary</b><p>This checkpoint demonstrates the activity and consent design. It does not claim live media delivery, production content moderation, identity verification, push delivery or payment processing.</p></div><button class="primary" data-demo-open="date-lifecycle">Review Virtual Date lifecycle</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}

function investorPilotReadiness(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">VIRTUAL DATING PILOT READINESS</div><h2>What a controlled pilot must prove</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">A decision-ready view for investors: Luma can demonstrate the structured dating journey now, while a real pilot must validate provider-backed operations, safety and economics before launch claims are made.</p><div class="demo-health-grid"><div class="ready"><span>PRODUCT PROOF</span><b>Structured date journey</b><small>15/30/60-minute options, optional games/questions/mini-dates, opt-in Truth or Dare, mutual extensions, voluntary exit and private post-date check-ins are represented and test-covered.</small></div><div class="ready"><span>PRIVACY RULE</span><b>Feedback stays private</b><small>1–5 ratings and date-again answers are private quality/matching inputs—not public attractiveness, popularity or leaderboard scores.</small></div><div class="ready"><span>FAIRNESS RULE</span><b>Unused time is reconcilable</b><small>Early-exit settlement logic can calculate unused prepaid time; real refund or credit execution remains blocked until an authoritative ledger and payment provider are connected.</small></div><div class="gated"><span>PILOT GATE</span><b>Provider-backed sessions</b><small>Identity/age verification, live voice/video, authenticated session events, secure media and push delivery need real providers and end-to-end validation.</small></div><div class="gated"><span>PILOT GATE</span><b>Safety operations</b><small>Moderation staffing, escalation procedures, abuse monitoring, retention/deletion controls and incident response must be operational before a controlled external pilot.</small></div><div class="gated"><span>PILOT GATE</span><b>Money + legal</b><small>Transactional storage, payment/refund/credit and payout rails, public legal/support URLs, production signing and store review remain release gates.</small></div></div><div class="provider-boundary"><b>Investor decision point</b><p>The next meaningful proof is not another mock metric: it is a controlled pilot that measures invitation acceptance, date completion, mutual extensions, early exits, safety outcomes, private quality signals and provider-backed unit economics.</p></div><button class="primary" data-demo-open="runbook">Open investor runbook</button><button class="secondary" data-demo-open="pilot-scorecard">Review pilot scorecard</button><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
function investorReleaseProof(){modal=modalWrap(`<div class="section-title"><div><div class="eyebrow">RELEASE PROOF</div><h2>Hardening that fails closed</h2></div><button class="icon-btn" data-close>×</button></div><p class="muted">The investor demo now separates release architecture that is implemented and test-covered from credentials and provider validation that still must happen outside this package.</p><div class="checkpoint-grid"><div><b>✓ Release signing architecture</b><small>Android release tasks require all four environment-supplied signing values and refuse debug-key fallback.</small></div><div><b>✓ Source integrity</b><small>Core source, test and release-evidence files are SHA-256 fingerprinted for this checkpoint.</small></div><div><b>✓ Virtual Dating behavior</b><small>15/30/60-minute configuration, mutual extensions, voluntary exit, settlement rules and private feedback remain test-covered.</small></div><div><b>⚠ External proof still required</b><small>A protected upload key, signed AAB inspection, Play App Signing, device testing, live providers and real credentials are not included or claimed.</small></div></div><div class="policy-card"><b>Investor-safe release statement</b><p>Luma has testable release-hardening architecture; it is not a signed, provider-validated or Google Play-approved production release.</p></div><button class="secondary" id="back-investor-tour">Back to product showcase</button>`);render()}
